package com.shopsphere.network;
import java.net.*;import java.io.*;import java.sql.*;import java.util.concurrent.*;
/** Simple read-only socket inventory protocol: GET_STOCK <id> or GET_PRODUCT <id>. */
public class InventoryServer {
 public static void main(String[] args)throws Exception {int port=args.length>0?Integer.parseInt(args[0]):5050;ExecutorService pool=Executors.newFixedThreadPool(8);try(ServerSocket server=new ServerSocket(port)){System.out.println("Inventory socket server on port "+port);while(true){Socket socket=server.accept();pool.submit(()->handle(socket));}}}
 static void handle(Socket socket){try(Socket s=socket;BufferedReader in=new BufferedReader(new InputStreamReader(s.getInputStream()));PrintWriter out=new PrintWriter(s.getOutputStream(),true)){s.setSoTimeout(10000);String line=in.readLine();if(line==null||!line.matches("GET_(STOCK|PRODUCT) [0-9]{1,9}")){out.println("ERR invalid command");return;}String[] parts=line.split(" ");int id=Integer.parseInt(parts[1]);String sql=parts[0].equals("GET_STOCK")?"SELECT stock FROM products WHERE product_id=?":"SELECT name,stock,price FROM products WHERE product_id=?";try(Connection c=DriverManager.getConnection(System.getenv().getOrDefault("SHOPSPHERE_DB_URL","jdbc:mysql://localhost:3306/shopsphere"),System.getenv().getOrDefault("SHOPSPHERE_DB_USER","root"),System.getenv().getOrDefault("SHOPSPHERE_DB_PASSWORD",""));PreparedStatement q=c.prepareStatement(sql)){q.setInt(1,id);try(ResultSet r=q.executeQuery()){if(!r.next())out.println("NOT_FOUND");else if(parts[0].equals("GET_STOCK"))out.println("STOCK "+r.getInt(1));else out.println("PRODUCT "+r.getString(1)+" | "+r.getInt(2)+" | "+r.getBigDecimal(3));}}}catch(Exception e){System.err.println("Client error: "+e.getMessage());}}
}
